function GameQuiniela({picks,setPicks,round,setRound,saved,onSave}:{picks:Record<string,string>,setPicks:(value:Record<string,string>|((prev:Record<string,string>)=>Record<string,string>))=>void,round:number,setRound:(round:number)=>void,saved:boolean,onSave:()=>void}){
 const [saving,setSaving]=useState(false); const [savedPulse,setSavedPulse]=useState(false); const [saveMessage,setSaveMessage]=useState("Enviado!"); const games=weeklyTeams.map(team=>({name:team,...(quizFixtures[round][team]||{})}));
 const playableGames=games.filter(game=>game.status!=="rest");
 const done=playableGames.filter(game=>picks[`${round}:${game.name}`]).length;
 const pending=playableGames.filter(game=>!game.opponent).length;
 const parseKickoff=(date?:string,time?:string)=>{if(!date||!time)return null;const [d,m,y]=date.split("/").map(Number);const [h,min]=time.split(":").map(Number);if(!d||!m||!y||Number.isNaN(h)||Number.isNaN(min))return null;return new Date(y,m-1,d,h,min).getTime()};
 const kickoffs=playableGames.map(g=>parseKickoff(g.date,g.time)).filter((v):v is number=>v!==null);
 const firstKickoff=kickoffs.length?Math.min(...kickoffs):null;
 const roundClosed=firstKickoff!==null&&Date.now()>=firstKickoff;
 return <section className="tabPage">
  <div className="pageTop compactTop"><div className="roundBadge"><i/> {roundClosed?"JORNADA CERRADA":round===1?"JORNADA ABIERTA":"PRÓXIMAMENTE"}</div><h1>Tu quiniela</h1><p>Toca 1, X o 2 en cada partido.</p></div>
  <div className="quizRounds singleRound" role="group" aria-label="Jornada publicada"><button type="button" aria-pressed="true" className="active">Jornada 1</button></div>
  <div className={"roundProgress "+(done===6?"complete":"")}><b>{done}/6</b><div><i style={{width:`${done/6*100}%`}}/></div><span>{done===6?"¡Jornada completada!":"Te faltan "+(6-done)+" pronósticos"}</span></div>
  <div className="matchStack">{games.map((game,i)=>{
   const {name:team,date="",time="",venue="",federationRound,competition}=game;
   const rival=game.opponent||"Rival por confirmar";
   const isHome=game.isHome!==false;
   const home=isHome?team:rival,away=isHome?rival:team;
   const label=competition==="Amistoso"?"AMISTOSO":federationRound?`${competition||"Liga"} · Jornada ${federationRound}`:`JORNADA DE LIGA PENDIENTE`;
   const pickKey=`${round}:${team}`;
   if(game.status==="rest")return <article className="matchCard restCard" key={team}><div className="matchMeta"><span>CADETE B · JORNADA 1</span><em>Descanso</em></div><div className="restTeam"><ClubCrest src="https://bwonxnayayopbohxuphs.supabase.co/storage/v1/object/public/Images/Escudos/cd_derio.png" name="CD Derio"/><div><b>CD Derio Cadete B</b><small>Entrenador · Gaizka Garcia</small></div></div><div className="restNotice">Esta jornada no disputa partido</div></article>;
   return <article className={"matchCard "+(picks[pickKey]?"picked":"")} key={team}>
    <div className="matchMeta"><span>{label}</span><em>{roundClosed?"Jornada cerrada":time?"Jornada abierta":"Hora pendiente"}</em></div>
    <div className="fixtureInfo"><span>{date?`${date} · ${time||"Hora por confirmar"}`:competition==="Amistoso"?"Este fin de semana · Hora por confirmar":"Fecha por confirmar"}</span><span>{venue||"Lugar por confirmar"}</span></div>
    <div className="versus"><div><ClubCrest src={isHome?"https://bwonxnayayopbohxuphs.supabase.co/storage/v1/object/public/Images/Escudos/cd_derio.png":game.crest||rivalCrests[team]} name={home}/><b>{home}</b><small>{game.isHome===undefined?"DERIO":"LOCAL"}</small></div><strong>VS</strong><div><ClubCrest src={isHome?game.crest||rivalCrests[team]:"https://bwonxnayayopbohxuphs.supabase.co/storage/v1/object/public/Images/Escudos/cd_derio.png"} name={away}/><b>{away}</b><small>{game.isHome===undefined?"POR CONFIRMAR":"VISITANTE"}</small></div></div>
    <div className="pickHint">ELIGE TU PRONÓSTICO</div>
    <div className="oneXtwo">{["1","X","2"].map(x=><button disabled={roundClosed||!game.opponent} aria-label={`${x}: ${x==="1"?`gana ${home}`:x==="X"?"empate":`gana ${away}`}`} aria-pressed={picks[pickKey]===x} className={picks[pickKey]===x?"active":""} onClick={()=>setPicks(v=>({...v,[pickKey]:x}))} key={x}><b>{x}</b><small>{x==="1"?"LOCAL":x==="X"?"EMPATE":"VISITANTE"}</small></button>)}</div>
    {picks[pickKey]&&<div className="pickFeedback">Pronóstico: <b>{picks[pickKey]}</b><span>Guardado localmente</span></div>}
   </article>
  })}</div>
  <div className="roundDock"><div className="roundDockStatus"><b>{roundClosed?"Jornada cerrada":done===6?"Pronóstico completo":done+"/6 elegidos"}</b><small>{roundClosed?"El primer partido ya ha comenzado":pending?`Pendientes ${pending} rivales por confirmar`:done===6?"Puedes revisar tus elecciones antes de enviarlas":"Completa todos los partidos"}</small></div><button className="savePrediction" disabled={done<6||roundClosed||pending>0||saving} onClick={()=>{const wasSaved=saved;setSaving(true);setSavedPulse(false);window.setTimeout(()=>{onSave();setSaving(false);setSaveMessage(wasSaved?"Actualizado!":"Enviado!");setSavedPulse(true);window.setTimeout(()=>setSavedPulse(false),1800)},180)}}><span>{saving?"Guardando…":saved?"Actualizar pronóstico":"Confirmar pronóstico"}</span></button>{savedPulse&&<div className="predictionSaved" role="status">{saveMessage}</div>}</div>
 </section>
}
function DinioImage(){const [failed,setFailed]=useState(false);return failed?<div className="dinioFallback" role="img" aria-label="Imagen de Dinio pendiente"><img src="https://bwonxnayayopbohxuphs.supabase.co/storage/v1/object/public/Images/Escudos/cd_derio.png" alt=""/><strong>DINIO</strong></div>:<img src="/dinio.png" alt="Dinio y CD Derio" onError={()=>setFailed(true)}/>;}
