function ClubCrest({src,name}:{src?:string,name:string}){const iturrigorri=/iturrigorri/i.test(name)||/Iturrigorri\.png/i.test(src||"");return src?<span className={"crestBox "+(iturrigorri?"crestIturrigorri":"")}><img src={src} alt={`Escudo de ${name}`} loading="lazy"/></span>:<i aria-hidden="true">?</i>}
function MyPredictions({picks,round,dinio,season,onEdit}:{picks:Record<string,string>,round:number,dinio:string,season:Season,onEdit:()=>void}){
 const [scope,setScope]=useState<"season"|"rounds">("season");
 const [view,setView]=useState<"mine"|"rivals">("mine");
 const [selectedRound,setSelectedRound]=useState(round);
 const availableRounds=[1,2,3,4,5,6,7,8];
 const total=teams.filter(team=>picks[`${selectedRound}:${team}`]).length;
 const seasonRows=[
  ...teamData.map(t=>({label:`${t.name} · Posición final`,value:season.positions[t.name]?season.positions[t.name]+"º":"—"})),
  {label:"Derio que queda más arriba",value:season.highest||"—"},
  {label:"Derio que queda más abajo",value:season.lowest||"—"},
  {label:"Primer entrenador expulsado",value:season.firstCoach||"—"},
  {label:"Entrenador con más tarjetas",value:season.coachCards||"—"},
  {label:"Primer delegado expulsado",value:season.firstDelegate||"—"},
  {label:"Delegado con más tarjetas",value:season.delegateCards||"—"},
  {label:"¿Dimitirá Dinio esta temporada?",value:dinio||"—"}
 ];
 return <section className="tabPage predictionsPage">
  <div className="pageTop porraPageTop"><p className="eyebrow">PRONÓSTICOS</p><h1>{scope==="season"?"Temporada":`Jornada ${selectedRound}`}</h1><p>{scope==="season"?"Consulta las predicciones iniciales de toda la temporada.":"Consulta los pronósticos 1/X/2 de cada jornada."}</p></div>
  <div className="predictionScopeTabs" role="tablist"><button role="tab" aria-selected={scope==="season"} className={scope==="season"?"active":""} onClick={()=>setScope("season")}>Temporada</button><button role="tab" aria-selected={scope==="rounds"} className={scope==="rounds"?"active":""} onClick={()=>setScope("rounds")}>Jornadas</button></div>
  <div className="predictionTabs" role="tablist"><button role="tab" aria-selected={view==="mine"} className={view==="mine"?"active":""} onClick={()=>setView("mine")}>Mis pronósticos</button><button role="tab" aria-selected={view==="rivals"} className={view==="rivals"?"active":""} onClick={()=>setView("rivals")}>Pronósticos rivales</button></div>
  {scope==="season"?(view==="mine"?<div className="seasonStickerGrid">{teamData.map(t=><article className="seasonSticker teamSticker" key={t.name}><div className="stickerPhoto"><img src={t.photo} alt={t.coach}/><span>{t.name}</span></div><div className="stickerCopy"><small>POSICIÓN FINAL</small><strong>{season.positions[t.name]?season.positions[t.name]+"º":"—"}</strong><b>{t.coach}</b></div></article>)}<article className="seasonSticker miniSticker"><small>MÁS ARRIBA</small><strong>↑</strong><b>{season.highest||"—"}</b></article><article className="seasonSticker miniSticker"><small>MÁS ABAJO</small><strong>↓</strong><b>{season.lowest||"—"}</b></article><article className="seasonSticker miniSticker coachSticker"><small>PRIMER ENTRENADOR EXPULSADO</small><strong className="redCardMark"></strong><b>{season.firstCoach||"—"}</b></article><article className="seasonSticker miniSticker coachSticker"><small>MÁS TARJETAS · ENTRENADOR</small><strong className="twoCardIcons" aria-hidden="true"><i></i><i></i></strong><b>{season.coachCards||"—"}</b></article><article className="seasonSticker miniSticker"><small>PRIMER DELEGADO EXPULSADO</small><strong className="redCardMark"></strong><b>{season.firstDelegate||"—"}</b></article><article className="seasonSticker miniSticker"><small>MÁS TARJETAS · DELEGADO</small><strong className="cardsMark" aria-hidden="true"></strong><b>{season.delegateCards||"—"}</b></article><article className="seasonSticker dinioSticker"><img src={SB+"/entrenadores/DinioDerio.jpeg"} alt="Dinio"/><div><small>EXTRA · TEMPORADA</small><b>¿Dimitirá Dinio?</b><strong>{dinio||"—"}</strong></div></article></div>:<section className="rivalsPanel rivalsTab"><div><p className="eyebrow">TEMPORADA</p><h2>Pronósticos de los rivales</h2><p>Predicciones iniciales de temporada de los demás participantes.</p></div><div className="rivalsEmpty"><UsersIcon/><b>Aún no hay pronósticos publicados</b><small>Se mostrarán jugador por jugador cuando estén disponibles.</small></div></section>):<>
   <div className="roundPredictionTabs">{availableRounds.map(n=><button type="button" className={selectedRound===n?"active":""} onClick={()=>setSelectedRound(n)} key={n}>J{n}</button>)}</div>
   {view==="mine"?<><div className="predictionSummary"><div><small>COMPLETADOS</small><b>{total}<em>/6</em></b></div><span>{total===6?"Jornada completa":"Te faltan "+(6-total)}</span></div><div className="myPicks fixturePicks">{teams.map(team=>{const game={name:team,...(quizFixtures[selectedRound]?.[team]||{})};const rival=game.opponent||"Rival por confirmar";const isHome=game.isHome!==false;const home=isHome?team:rival,away=isHome?rival:team;return <button type="button" className="myPick fixturePick" onClick={onEdit} key={team}><div className="fixtureCrests"><ClubCrest src={isHome?"https://bwonxnayayopbohxuphs.supabase.co/storage/v1/object/public/Images/Escudos/cd_derio.png":game.crest||rivalCrests[team]} name={home}/><ClubCrest src={isHome?game.crest||rivalCrests[team]:"https://bwonxnayayopbohxuphs.supabase.co/storage/v1/object/public/Images/Escudos/cd_derio.png"} name={away}/></div><div className="fixturePickCopy"><b><span>{home}</span><em>vs</em><span>{away}</span></b><small>{game.date||"Fecha pendiente"} · {game.time||"Hora pendiente"}</small></div><strong className={"pickResult "+(picks[`${selectedRound}:${team}`]?"hasPick":"")}>{picks[`${selectedRound}:${team}`]||"—"}</strong></button>})}</div></>:<section className="rivalsPanel rivalsTab"><div><p className="eyebrow">JORNADA {selectedRound}</p><h2>Pronósticos de los rivales</h2><p>Pronósticos 1/X/2 publicados para esta jornada.</p></div><div className="rivalsEmpty"><UsersIcon/><b>Aún no hay pronósticos publicados</b><small>Se mostrarán jugador por jugador en esta jornada.</small></div></section>}
  </>}
 </section>
}
function Ranking({mode,setMode}:{mode:"general"|"jornada",setMode:(m:"general"|"jornada")=>void}){return <section className="tabPage"><div className="pageTop porraPageTop"><p className="eyebrow">CLASIFICACIÓN</p><h1>{mode==="general"?"Clasificación general":"Clasificación de jornada"}</h1><p>{mode==="general"?"Puntos acumulados durante la temporada.":"Puntos conseguidos en la jornada actual."}</p></div><div className="rankingTabs"><button className={mode==="general"?"active":""} onClick={()=>setMode("general")}>General</button><button className={mode==="jornada"?"active":""} onClick={()=>setMode("jornada")}>Jornada</button></div><div className="leaderCard"><div><span>1</span><div><b>Sin líder aún</b><small>La clasificación aparecerá con las primeras puntuaciones</small></div><strong>0 <em>pts</em></strong></div></div><div className="rankingHeader"><span>#</span><span>JUGADOR</span><span>PTS</span></div><div className="rankingEmpty porraEmpty">Todavía no hay puntuaciones registradas.</div></section>}
function More({name,dinio,season,onTab}:{name:string,dinio:string,season:Season,onTab:(tab:"inicio"|"quiniela"|"pronosticos"|"clasificacion"|"mas")=>void}){
 const [panel,setPanel]=useState<"season"|"extra"|"rules"|"name"|null>(null);
 const [theme,setTheme]=useState<"dark"|"light">("dark");
 const [pushEnabled,setPushEnabled]=useState(false); const [editName,setEditName]=useState(name); const [profilePic,setProfilePic]=useState(""); const [profileStatus,setProfileStatus]=useState(""); const [accountEmail,setAccountEmail]=useState("");
 useEffect(()=>{const t=(localStorage.getItem("quiniderio-theme") as "dark"|"light")||"dark";document.documentElement.dataset.nav="bottom";localStorage.removeItem("quiniderio-nav");setTheme(t);setPushEnabled(localStorage.getItem("quiniderio-notifications")==="true");try{const x=JSON.parse(localStorage.getItem("quiniderio-player")||"{}");setProfilePic(x.profilePic||"");setAccountEmail((x.email||"").toLowerCase())}catch{}},[]);
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem("quiniderio-theme",theme)},[theme]);
 useEffect(()=>{if(!panel)return;const close=(event:KeyboardEvent)=>{if(event.key==="Escape")setPanel(null)};const y=window.scrollY;const body=document.body;const prev={position:body.style.position,top:body.style.top,width:body.style.width,overflow:body.style.overflow};body.style.position="fixed";body.style.top=`-${y}px`;body.style.width="100%";body.style.overflow="hidden";window.addEventListener("keydown",close);return()=>{window.removeEventListener("keydown",close);body.style.position=prev.position;body.style.top=prev.top;body.style.width=prev.width;body.style.overflow=prev.overflow;window.scrollTo(0,y)}},[panel]);
 const toggleNotifications=async()=>{try{if(pushEnabled){await disablePush();setPushEnabled(false)}else if(await enablePush())setPushEnabled(true)}catch{setProfileStatus("No se han podido cambiar las notificaciones")}};
 return <section className="tabPage profilePage porraAccount">
  <div className="accountTitle"><p className="eyebrow">TEMPORADA 2026/27</p><h1>Mi cuenta</h1><p>Gestiona tu perfil, apariencia y datos de tu cuenta.</p></div>
  <div className="accountProfileCard">
   <div className="accountIdentity"><div className="bigAvatar">{profilePic?<img src={profilePic} alt="Foto de perfil"/>:name[0]?.toUpperCase()}</div><div><h2>{name}</h2><small>Jugador QuiniDerio · 0 pts</small></div></div>
   <div className="profilePhotoActions"><label className="photoAction"><span className="cameraIcon" aria-hidden="true"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3Z"/><circle cx="12" cy="13" r="3"/></svg></span>Cambiar foto<input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>5*1024*1024){setProfileStatus("La imagen supera 5 MB");e.currentTarget.value="";return}void compressProfileImage(f).then(async v=>{try{const {data:{user}}=await supabase.auth.getUser();if(user)await supabase.from("quini_profiles").update({profile_pic:v,updated_at:new Date().toISOString()}).eq("user_id",user.id);const x=JSON.parse(localStorage.getItem("quiniderio-player")||"{}");localStorage.setItem("quiniderio-player",JSON.stringify({...x,profilePic:v}));setProfilePic(v);setProfileStatus("Foto optimizada y guardada")}catch{setProfileStatus("No se pudo guardar la foto")}}).catch(()=>setProfileStatus("No se pudo procesar la foto"));e.currentTarget.value=""}}/></label><button type="button" className="removePhoto" disabled={!profilePic} onClick={async()=>{setProfilePic("");setProfileStatus("Foto eliminada");const {data:{user}}=await supabase.auth.getUser();if(user)await supabase.from("quini_profiles").update({profile_pic:"",updated_at:new Date().toISOString()}).eq("user_id",user.id);try{const x=JSON.parse(localStorage.getItem("quiniderio-player")||"{}");localStorage.setItem("quiniderio-player",JSON.stringify({...x,profilePic:""}))}catch{}}}>Eliminar foto</button></div>
   <small className="photoHint">JPG, PNG o WebP · Máximo 5 MB {profileStatus&&<b>· {profileStatus}</b>}</small>
   <div className="profileFields"><button type="button" className="profileNameButton" onClick={()=>{setEditName(name);setPanel("name")}}><span><small>NOMBRE EN LA PORRA</small><b>{name}</b><em>Este será el nombre que verán los demás participantes.</em></span><strong>Editar ›</strong></button></div>
  </div>
  <div className="accountSection accountQuick"><h3>Cuenta</h3><div className="accountList">
   <button type="button" onClick={()=>onTab("pronosticos")}><span><TargetIcon/></span><div><b>Mis pronósticos</b><small>Consulta tus pronósticos de jornada</small></div><em>›</em></button>
   <button type="button" onClick={()=>setPanel("rules")}><span><StandingsIcon/></span><div><b>Cómo se puntúa</b><small>Reglas y sistema de puntos</small></div><em>›</em></button>
  </div></div>
  <div className="accountSection"><h3>Apariencia</h3><div className="accountList settingList">
   <div className="settingRow"><span className="settingIcon">◐</span><div><b>Modo de visualización</b><small>Elige el aspecto de la aplicación</small></div><div className="segmented"><button className={theme==="dark"?"active":""} onClick={()=>setTheme("dark")}>Oscuro</button><button className={theme==="light"?"active":""} onClick={()=>setTheme("light")}>Claro</button></div></div>
   
  </div></div>
  <div className="accountSection"><h3>Notificaciones</h3><div className="accountList settingList"><div className="settingRow notificationSetting"><span className="settingIcon" aria-hidden="true"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg></span><div><b>Activar notificaciones</b><small>Avisos de pronósticos pendientes, cierre de jornada y resultados</small></div><button type="button" role="switch" aria-checked={pushEnabled} className={"switch "+(pushEnabled?"on":"")} onClick={toggleNotifications}><i/></button></div></div></div>
  {accountEmail==="gabrialzueta@gmail.com"&&<div className="accountSection adminAccountSection"><h3>Administración</h3><div className="accountList"><button type="button" className="adminPanelEntry" onClick={()=>{window.location.href="/admin"}}><span>⚙</span><div><b>Panel Admin</b><small>Gestionar jornada, resultados, goles y tarjetas</small></div><em>›</em></button></div></div>}
  <div className="accountSection sessionSection"><h3>Sesión</h3><div className="accountList"><button type="button" className="logoutAccount" onClick={async()=>{await supabase.auth.signOut();localStorage.removeItem("quiniderio-player");sessionStorage.clear();window.location.reload()}}><span aria-hidden="true">↪</span><div><b>Cerrar sesión</b><small>Salir de tu cuenta en este dispositivo</small></div><em>›</em></button><button type="button" className="deleteAccount" onClick={async()=>{if(window.confirm("¿Seguro que quieres eliminar tu cuenta? Esta acción borrará tu perfil, tus pronósticos y tus datos guardados y no se puede deshacer.")){const {data:{session}}=await supabase.auth.getSession();if(session){const res=await fetch("/api/account",{method:"DELETE",headers:{Authorization:"Bearer "+session.access_token}});if(!res.ok){setProfileStatus("No se ha podido eliminar la cuenta");return}}await supabase.auth.signOut();localStorage.removeItem("quiniderio-player");localStorage.removeItem("quiniderio-player-id");localStorage.removeItem("quiniderio-picks");localStorage.removeItem("quiniderio-saved-rounds");localStorage.removeItem("quiniderio-notifications");localStorage.removeItem("quiniderio-federation-cache");sessionStorage.clear();window.location.reload()}}}><span aria-hidden="true">×</span><div><b>Eliminar cuenta</b><small>Eliminar permanentemente tu cuenta y sus datos</small></div><em>›</em></button></div></div>
  {panel&&<div className="detailBackdrop" onClick={()=>setPanel(null)}><section role="dialog" aria-modal="true" className={"detailSheet "+(panel==="name"?"nameSheet":"")} onClick={event=>event.stopPropagation()}><div className="detailSheetHead"><div><small>QUINIDERIO · 2026/27</small><h2>{panel==="extra"?"Predicción extra":panel==="name"?"Cambiar nombre":"Cómo se puntúa"}</h2></div><button type="button" aria-label="Cerrar" onClick={()=>setPanel(null)}>×</button></div>{panel==="name"&&<div className="nameEditor"><label>NOMBRE EN LA PORRA<input autoFocus maxLength={30} value={editName} onChange={e=>setEditName(e.target.value)} /></label><div><small>Lo verán los demás participantes.</small><b>{editName.length}/30</b></div><button type="button" disabled={editName.trim().length<3||editName.trim()===name} onClick={async()=>{const next=editName.trim();const {data:{user}}=await supabase.auth.getUser();if(user)await supabase.from("quini_profiles").update({username:next,updated_at:new Date().toISOString()}).eq("user_id",user.id);try{const x=JSON.parse(localStorage.getItem("quiniderio-player")||"{}");localStorage.setItem("quiniderio-player",JSON.stringify({...x,name:next}));setPanel(null);window.location.reload()}catch{}}}>Guardar nombre</button></div>}{panel==="extra"&&<div className="detailExtra"><p>¿Dimitirá Dinio esta temporada?</p><strong>{dinio||"Sin respuesta guardada"}</strong><small>Predicción confirmada · +5 puntos si aciertas</small></div>}{panel==="rules"&&<div className="detailRows">{[["Quiniela semanal","+1 punto por acierto"],["Posición final exacta","+20 puntos por equipo"],["Derio más arriba o abajo","+10 puntos cada uno"],["Entrenadores y delegados","+15 puntos por acierto"],["Predicción extra de Dinio","+5 puntos por acierto"]].map(([label,value])=><div className="detailRow" key={label}><span>{label}</span><b>{value}</b></div>)}</div>}</section></div>}
 </section>
}
function BottomNavigation({tab,onNavigate}:{tab:"inicio"|"quiniela"|"pronosticos"|"clasificacion"|"mas",onNavigate:(tab:"inicio"|"quiniela"|"pronosticos"|"clasificacion"|"mas")=>void}){return <nav className="liquidNav" aria-label="Navegación principal"><button aria-label="Inicio" aria-current={tab==="inicio"?"page":undefined} className={tab==="inicio"?"active":""} onClick={()=>onNavigate("inicio")}><span className="navIcon"><HomeIcon/></span><small>Inicio</small></button><button aria-label="Quiniela" aria-current={tab==="quiniela"?"page":undefined} className={tab==="quiniela"?"active":""} onClick={()=>onNavigate("quiniela")}><span className="navIcon"><TargetIcon/></span><small>Quiniela</small></button><button aria-label="Pronósticos" aria-current={tab==="pronosticos"?"page":undefined} className={tab==="pronosticos"?"active":""} onClick={()=>onNavigate("pronosticos")}><span className="navIcon"><UsersIcon/></span><small>Pronósticos</small></button><button aria-label="Clasificación" aria-current={tab==="clasificacion"?"page":undefined} className={tab==="clasificacion"?"active":""} onClick={()=>onNavigate("clasificacion")}><span className="navIcon"><StandingsIcon/></span><small>Clasificación</small></button><button aria-label="Mi cuenta" aria-current={tab==="mas"?"page":undefined} className={tab==="mas"?"active":""} onClick={()=>onNavigate("mas")}><span className="navIcon"><AccountIcon/></span><small>Mi cuenta</small></button></nav>}
function HomeIcon(){return <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="M3 10.5 12 3l9 7.5V21h-6v-6H9v6H3Z"/></svg>}
function TargetIcon(){return <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="M12 3a9 9 0 1 0 9 9"/><path d="M12 7a5 5 0 1 0 5 5"/><path d="M12 11a1 1 0 1 0 1 1"/><path d="m14.5 9.5 5-5"/><path d="M17 4.5h2.5V7"/></svg>}
function UsersIcon(){return <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><circle cx="8" cy="8" r="3"/><circle cx="16" cy="8" r="3"/><path d="M2.5 20v-1.5A4.5 4.5 0 0 1 7 14h2a4.5 4.5 0 0 1 4.5 4.5V20M14 14h1.5a4 4 0 0 1 4 4V20"/></svg>}
function StandingsIcon(){return <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="M4 20V10h4v10M10 20V4h4v16M16 20v-7h4v7M2 20h20"/></svg>}
function AccountIcon(){return <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></svg>}
